-- KosmoMat content pack. Generated by cmd/kosmobuild; read-only in the app.
PRAGMA user_version = 1;

CREATE TABLE meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE nodes (
  id            TEXT PRIMARY KEY,
  type          TEXT NOT NULL,
  status        TEXT,
  literature    TEXT,
  testability   TEXT,
  case_kind     TEXT,
  era           TEXT,
  astromat      INTEGER NOT NULL DEFAULT 0,
  first_year    INTEGER,
  first_by      TEXT,          -- JSON array of person ids
  first_work    TEXT REFERENCES works(key),
  first_loc     TEXT,
  last_verified TEXT NOT NULL,
  verified_by   TEXT NOT NULL,
  extra_json    TEXT           -- type-specific fields (experiment needs, difficulty…)
);

CREATE TABLE node_i18n (
  node_id     TEXT NOT NULL REFERENCES nodes(id),
  lang        TEXT NOT NULL,
  level       TEXT NOT NULL,   -- kid|lay|student
  title       TEXT NOT NULL,
  summary     TEXT NOT NULL,
  blocks_json TEXT NOT NULL,
  PRIMARY KEY (node_id, lang, level)
);

CREATE TABLE edges (
  src         TEXT NOT NULL,
  rel         TEXT NOT NULL,
  dst         TEXT NOT NULL,
  work_key    TEXT,
  locator     TEXT,
  note_json   TEXT,
  dst_exists  INTEGER NOT NULL  -- 0 = target card not written yet
);
CREATE INDEX edges_src ON edges(src);
CREATE INDEX edges_dst ON edges(dst);

CREATE TABLE works (
  key        TEXT PRIMARY KEY,
  tier       TEXT NOT NULL,
  kind       TEXT NOT NULL,
  title      TEXT NOT NULL,
  authors    TEXT NOT NULL,    -- JSON array
  year       INTEGER NOT NULL,
  venue      TEXT,
  doi        TEXT,
  arxiv      TEXT,
  bibcode    TEXT,
  isbn       TEXT,
  url        TEXT,
  country    TEXT,             -- JSON array of ISO codes
  retracted  INTEGER NOT NULL,
  verified   INTEGER NOT NULL
);

CREATE TABLE node_sources (
  node_id  TEXT NOT NULL REFERENCES nodes(id),
  work_key TEXT NOT NULL REFERENCES works(key),
  locator  TEXT NOT NULL,
  PRIMARY KEY (node_id, work_key, locator)
);

CREATE TABLE predictions (
  id                      TEXT PRIMARY KEY,
  theory                  TEXT NOT NULL,
  statement_json          TEXT NOT NULL,
  made_year               INTEGER,
  made_by                 TEXT,
  made_work               TEXT,
  made_loc                TEXT,
  made_before_observation INTEGER NOT NULL,
  retrodiction            INTEGER NOT NULL,
  test_year               INTEGER,
  test_obs                TEXT,
  test_by                 TEXT,
  test_work               TEXT,
  test_loc                TEXT,
  outcome                 TEXT NOT NULL,
  note_json               TEXT,
  has_card                INTEGER NOT NULL  -- 1 = own pred.* node
);
CREATE INDEX predictions_theory ON predictions(theory);

CREATE TABLE media (
  id         TEXT PRIMARY KEY,
  node_id    TEXT NOT NULL,
  sha256     TEXT NOT NULL,
  ext        TEXT NOT NULL,
  credit     TEXT NOT NULL,
  license    TEXT NOT NULL,
  source_url TEXT NOT NULL,
  w          INTEGER,
  h          INTEGER
);

CREATE TABLE changelog (
  node_id  TEXT NOT NULL,
  date     TEXT NOT NULL,
  kind     TEXT NOT NULL,
  note     TEXT NOT NULL,
  work_key TEXT
);
CREATE INDEX changelog_date ON changelog(date DESC);

CREATE TABLE paths (
  slug       TEXT PRIMARY KEY,
  title_json TEXT NOT NULL,
  nodes_json TEXT NOT NULL
);

CREATE TABLE redirects (
  old_id TEXT PRIMARY KEY,
  new_id TEXT NOT NULL
);

CREATE VIRTUAL TABLE search USING fts5(
  node_id UNINDEXED,
  lang UNINDEXED,
  title,
  summary,
  body,
  tokenize = 'unicode61 remove_diacritics 2'
);
